function loadPackageExports(request, dir, conditions) {
  const pkgDir = parsePackageName(request) // { name, subpath }
  if (!pkgDir) return null
  const pkgPath = path.join(dir, pkgDir.name, 'package.json')
  if (!isFile(pkgPath)) return null
  const pkg = readPackage(pkgPath)
  if (!pkg || !pkg.exports) return null
  const key = pkgDir.subpath ? `.${pkgDir.subpath}` : '.'
  const target = resolveExports(pkg.exports, key, conditions)
  if (!target) return null
  const resolved = path.resolve(path.join(dir, pkgDir.name), target)
  return loadAsFileOrDirectory(resolved, DEFAULT_EXTENSIONS)
}

